const straightColors=[['Нержавейка светлая','#bbc1c3'],['Нержавейка тёмная','#817b61'],['Нержавейка графит','#56636d'],['Нержавейка чёрная','#343d44'],['Нержавейка золото','#b8a17b'],['Чёрный браш','#343539'],['Чёрный матовый','#252527'],['Латунь браш','#af936b'],['Золото браш','#c9ad55']];
const curvedColors=[['Медь','#a77b63'],['Чёрный','#333638'],['Серебро','#c0c6c8'],['Светлое золото','#cbb46d'],['Розовое золото','#c69891']];
const scenes=['Во весь рост','Над двумя умывальниками','Над консолью'];
const finishes={3:[6,8,2],8:[7,2,0],15:[1,6,8],20:[5,4,0],50:[3,7,6]};
const descriptions={3:'Едва заметная линия вокруг отражения.',8:'Тонкий контур для сдержанного интерьера.',15:'Аккуратная рамка с заметной фактурой металла.',20:'Выразительная линия и ясная геометрия.',50:'Широкая плоская рама как самостоятельный акцент.'};
const dialog=document.querySelector('#image-dialog');
function photo(src,title,caption,note=''){const card=document.createElement('article');card.className='photo-card';const button=document.createElement('button');button.type='button';button.setAttribute('aria-label','Увеличить: '+title+' — '+caption);const img=document.createElement('img');img.src=src;img.alt=title+' — '+caption;img.loading='lazy';button.append(img);button.onclick=()=>{dialog.querySelector('img').src=src;dialog.querySelector('img').alt=img.alt;dialog.querySelector('p').textContent=img.alt;dialog.showModal()};const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=caption;const buy=document.createElement('button');buy.type='button';buy.className='buy-mirror';buy.textContent='Выбрать зеркало →';buy.onclick=()=>window.dispatchEvent(new CustomEvent('mirror-buy',{detail:{src,title,caption,note}}));const info=document.createElement('div');info.className='photo-info';const text=document.createElement('div');text.append(h,p);info.append(text,buy);card.append(button,info);return card}
[['Круг','Медь'],['Овал','Чёрный'],['Капсула','Серебро'],['Скруглённые углы','Светлое золото'],['Свободный контур','Розовое золото · Подсветка'],['Плавная волна','Чёрный']].forEach(([name,finish],i)=>document.querySelector('#curved-gallery').append(photo('assets/mirrors/curved-'+(i===4?'7-lit':i+1)+'.png',name,finish,i===4?'Лицевая подсветка световой линией по контуру и сенсор включения/выключения.':'')));
function selectProfile(width){document.querySelectorAll('.profile-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.width===width)));document.querySelector('#profile-heading').textContent='Лицевая часть '+width+' мм';document.querySelector('#profile-description').textContent=descriptions[width];const glass=document.querySelector('#scale-glass');Object.entries({x:width,y:width,width:600-2*width,height:900-2*width}).forEach(([k,v])=>glass.setAttribute(k,v));document.querySelector('#straight-gallery').replaceChildren(...scenes.map((name,i)=>photo('assets/mirrors/straight-'+width+'-'+(i+1)+'.png',name,straightColors[finishes[width][i]][0]+' · профиль '+width+' мм')))}
[3,8,15,20,50].forEach(width=>{const b=document.createElement('button');b.type='button';b.textContent=width+' мм';b.dataset.width=width;b.onclick=()=>selectProfile(width);document.querySelector('.profile-tabs').append(b)});selectProfile(3);
function swatches(id,colors){colors.forEach(([name,color],index)=>{const item=document.createElement('div');item.className='swatch'+(name==='Чёрный матовый'?' matte':'');const sample=document.createElement('span');sample.style.setProperty('--finish',color);if(id==='#straight-swatches'){const cell=[0,1,2,3,6,4,5,7,8][index];const x=[2.38,49.11,97.52][cell%3],y=[6.42,44.83,82.64][Math.floor(cell/3)];sample.style.backgroundImage='url(assets/mirrors/straight-finishes.png)';sample.style.backgroundSize='329.09% 443.27%';sample.style.backgroundPosition=x+'% '+y+'%';sample.style.backgroundRepeat='no-repeat';}if(id==='#curved-swatches'){sample.style.backgroundImage='url(assets/mirrors/curved-finishes.png)';sample.style.backgroundSize='500% 100%';sample.style.backgroundPosition=([0,1,2,4,0][index]*25)+'% 50%';sample.style.backgroundRepeat='no-repeat';}if(id==='#curved-swatches'&&name==='Розовое золото')sample.style.filter='hue-rotate(-25deg) saturate(0.65) brightness(1.12)';const p=document.createElement('p');p.textContent=name;item.append(sample,p);document.querySelector(id).append(item)})}swatches('#straight-swatches',straightColors);swatches('#curved-swatches',curvedColors);
dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
